// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Ensure the caller is the owner (which is address(0) initially in the deployment)
        vm.assume(newOwner != address(0));
        // Set owner to newOwner via transferOwnership (but c.owner() is still address(0) at this point)
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        // Now call owned() as the new owner
        vm.prank(newOwner);
        c.owned();
        // After owned(), the public getter should return newOwner (not address(0))
        assertTrue(c.owner() == newOwner);
    }
}

